contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Setup: give the test contract some balance in c.
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        // Before the deciding call, read the caller's recorded balance.
        uint before = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        // Deciding call: withdrawBalance must complete without reverting.
        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        // Read observable state after the call.
        uint afterBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        assert(
            !reverted &&
            afterBal == 0 &&
            thisBalanceAfter == thisBalanceBefore + before &&
            cBalanceAfter == cBalanceBefore - before
        );
    }

    receive() external payable {}
}

