// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 before;
        try c.getBalance(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint256 afterBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;
        assertTrue(!reverted &&
            afterBal == 0 &&
            thisBalanceAfter == thisBalanceBefore + before &&
            cBalanceAfter == cBalanceBefore - before);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
